// Icon mapping
const iconMap = {
  Bot,
  BrainCircuit,
  Cog,
  Code,
  CodeXml,
  Palette,
  Smartphone,
  Globe,
  TrendingUp,
  Cloud,
  Sparkles,
  Zap,
  Shield,
  Layers,
  Monitor,
