  );
}

// Dashboard Stats Component
function DashboardStats({ stats, isLoading, error, onRetry, onRelogin }) {
  if (isLoading) {
    return <div className="text-gray-400">Loading statistics...</div>;
  }

  if (error) {
    return (
      <div className="space-y-4">
        <h2 className="text-2xl font-bold text-white">Dashboard Overview</h2>
        <div className="bg-red-500/10 border border-red-500/30 rounded-xl p-6">
          <div className="flex items-center gap-3 text-red-400">
            <AlertTriangle className="w-6 h-6" />
            <p className="font-semibold">Error: something went wrong</p>
          </div>
          <p className="text-gray-400 text-sm mt-2">{error.message}</p>
          <div className="flex flex-wrap gap-3 mt-4">
            <Button
              onClick={onRetry}
              className="bg-[#FFB633] text-black hover:bg-[#e5a32e]"
            >
              <RefreshCw className="w-4 h-4 mr-2" />
              Retry
            </Button>
            {error.status === 401 && onRelogin && (
              <Button
                onClick={onRelogin}
                variant="outline"
                className="border-white/20 text-gray-300 hover:text-white"
              >
                Log in again
              </Button>
            )}
          </div>
        </div>
      </div>
    );
  }

  const chartData = [
    { name: "Users", value: stats.users || 0, color: "#3B82F6" },
    { name: "Projects", value: stats.projects || 0, color: "#10B981" },
    { name: "Services", value: stats.services || 0, color: "#8B5CF6" },
    { name: "Testimonials", value: stats.testimonials || 0, color: "#F97316" },
    { name: "Messages", value: stats.messages || 0, color: "#EC4899" },
  ];

  const statCards = [
    {
      label: "Total Users",
      value: stats.users || 0,
      icon: Users,
      color: "bg-blue-500",
    },
    {
      label: "Projects",
      value: stats.projects || 0,
      icon: FolderKanban,
      color: "bg-green-500",
    },
    {
      label: "Services",
      value: stats.services || 0,
      icon: Briefcase,
      color: "bg-purple-500",
    },
    {
      label: "Testimonials",
      value: stats.testimonials || 0,
      icon: MessageSquare,
      color: "bg-orange-500",
    },
    {
      label: "Messages",
      value: stats.messages || 0,
      icon: Mail,
      color: "bg-pink-500",
    },
  ];

  return (
    <div className="space-y-8">
      <div>
        <h2 className="text-2xl font-bold text-white mb-6">
          Dashboard Overview
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
          {statCards.map((stat) => (
            <motion.div
              key={stat.label}
              whileHover={{ scale: 1.02 }}
              className="bg-[#1a1a1b] rounded-xl p-6 border border-white/10"
            >
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-gray-400 text-sm">{stat.label}</p>
                  <p className="text-3xl font-bold text-white mt-2">
                    {stat.value}
                  </p>
                </div>
                <div className={`${stat.color} p-3 rounded-lg`}>
                  <stat.icon className="w-6 h-6 text-white" />
                </div>
              </div>
            </motion.div>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-[#1a1a1b] rounded-xl p-6 border border-white/10">
          <h3 className="text-lg font-semibold text-white mb-4">
            Statistics Overview
          </h3>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#333" />
              <XAxis dataKey="name" stroke="#888" />
              <YAxis stroke="#888" />
              <Bar dataKey="value" fill="#FFB633" radius={[4, 4, 0, 0]} />
              <Tooltip
                contentStyle={{
                  backgroundColor: "#1a1a1b",
                  border: "1px solid #333",
                }}
                labelStyle={{ color: "#fff" }}
              />
            </BarChart>

function AdminPageInner() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const { user, logout, loading, getAuthHeaders } = useAuth();
  const { channels: chatChannels } = useChatChannels();
  const totalUnreadChat = chatChannels.reduce(
    (sum, c) => sum + (c.unreadCount || 0),
    0,
  );
  const [activeTab, setActiveTab] = useState("dashboard");
  const [highlightId, setHighlightId] = useState(null);
  const [highlightMilestoneId, setHighlightMilestoneId] = useState(null);
  const [highlightProposalId, setHighlightProposalId] = useState(null);
  const [isMobileOpen, setIsMobileOpen] = useState(false);
  const [stats, setStats] = useState({});
  const [statsLoading, setStatsLoading] = useState(true);
  const [statsError, setStatsError] = useState(null);

  useEffect(() => {
    if (!loading && (!user || !user.isAdmin)) {
      router.push("/");
    }
  }, [user, loading, router]);

  // Deep-link from a notification: ?tab=<section>&id=<cardId>&m=<milestoneId>
  useEffect(() => {
    const tab = searchParams.get("tab");
    if (tab && ADMIN_TABS.includes(tab)) {
      setActiveTab(tab);
      localStorage.setItem(ADMIN_TAB_STORAGE_KEY, tab);
    } else {
      const storedTab = localStorage.getItem(ADMIN_TAB_STORAGE_KEY);
      if (storedTab && ADMIN_TABS.includes(storedTab)) {
        setActiveTab(storedTab);
      }
    }
    setHighlightId(searchParams.get("id") || null);
    setHighlightMilestoneId(searchParams.get("m") || null);
    setHighlightProposalId(searchParams.get("proposal") || null);
  }, [searchParams]);

  const handleTabChange = (tab) => {
    if (!ADMIN_TABS.includes(tab)) return;
    setActiveTab(tab);
    localStorage.setItem(ADMIN_TAB_STORAGE_KEY, tab);
    setHighlightId(null);
    setHighlightMilestoneId(null);
    setHighlightProposalId(null);

    const params = new URLSearchParams(searchParams.toString());
    params.set("tab", tab);
    params.delete("id");
    params.delete("m");
    params.delete("proposal");
    router.replace(`/admin?${params.toString()}`, { scroll: false });
  };

  useEffect(() => {
    if (user?.isAdmin) {
      fetchStats();
    }
  }, [user]);

  const fetchStats = async () => {
    setStatsLoading(true);
    setStatsError(null);
    try {
      const response = await axios.get("/api/statistics", {
        headers: getAuthHeaders(),
      });
      setStats(response.data);
    } catch (error) {
      console.error("Failed to fetch stats:", error);
      const status = error.response?.status;
      setStatsError({
        status,
        message:
          status === 401
            ? "Your session has expired. Please log in again."
            : error.response?.data?.error ||
              "Something went wrong while loading statistics.",
      });
    } finally {
      setStatsLoading(false);
    }
  };

  const handleLogout = () => {
    logout();
    toast.success("Logged out successfully");
    router.push("/");
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-[#0f0f10] flex items-center justify-center">
        <div className="text-white">Loading...</div>
      </div>
    );
  }

  if (!user || !user.isAdmin) {
    return null;
  }

  const renderContent = () => {
    switch (activeTab) {
      case "dashboard":
        return (
          <DashboardStats
            stats={stats}
            isLoading={statsLoading}
            error={statsError}
            onRetry={fetchStats}
            onRelogin={handleLogout}
          />
        );
      case "services":
        return <ServicesManagement />;
      case "projects":
        return <ProjectsManagement />;
      case "client-projects":
        return (
          <ClientProjectsManager
            highlightId={highlightId}
            highlightMilestoneId={highlightMilestoneId}
            highlightProposalId={highlightProposalId}
          />
        );
      case "chat":
        return (
          <ProjectChat
            viewerRole="admin"
            initialChannelId={searchParams.get("channel")}
          />
        );
      case "project-requests":
        return <ProjectRequestsManager highlightId={highlightId} />;
      case "testimonials":
        return <TestimonialsManagement highlightId={highlightId} />;
      case "users":
        return <UsersManagement />;
      case "messages":
        return <MessagesManagement highlightId={highlightId} />;
      case "company":
        return <CompanyProfileManagement />;
      case "cms":
        return <CMSPagesManagement />;
      default:
        return (
          <DashboardStats
            stats={stats}
            isLoading={statsLoading}

            isLoading={statsLoading}
            error={statsError}
            onRetry={fetchStats}
            onRelogin={handleLogout}
          />
        );
    }
  };

  return (
    <div className="min-h-screen bg-[#0f0f10]">
      <PushManager />
      <AdminSidebar
        activeTab={activeTab}
        setActiveTab={handleTabChange}
        onLogout={handleLogout}
        isMobileOpen={isMobileOpen}
        setIsMobileOpen={setIsMobileOpen}
        totalUnreadChat={totalUnreadChat}
      />

      {/* Main Content */}
      <div className="lg:ml-64">
        {/* Top Bar */}
        <header className="bg-[#1a1a1b] border-b border-white/10 px-2 lg:px-6 py-4">
          <div className="flex items-center justify-between">
            <button
              onClick={() => setIsMobileOpen(true)}
              className="lg:hidden p-2 text-gray-400 hover:text-white"
            >
              <Menu className="w-6 h-6" />
            </button>
            <div className="flex items-center gap-4 ml-auto">
              <Link
                href="/"
                className="text-gray-400 hover:text-white transition-colors flex items-center gap-2"
              >
                <Home className="w-4 h-4" />
                <span className="hidden sm:inline">Home</span>
              </Link>
              <NotificationBell variant="admin" />
              <span className="text-gray-400 text-sm">
                Welcome, {user?.name}
              </span>
              <div className="w-10 h-10 rounded-full bg-[#FFB633]/20 flex items-center justify-center">
                <Users className="w-5 h-5 text-[#FFB633]" />
              </div>
            </div>
          </div>
        </header>

        {/* Page Content */}
        <main className="p-6">{renderContent()}</main>
      </div>
    </div>
  );
}

export default function AdminPage() {
  return (
    <Suspense
      fallback={
        <div className="min-h-screen bg-[#0f0f10] flex items-center justify-center">
          <div className="text-white">Loading...</div>
        </div>
      }
    >
      <AdminPageInner />
    </Suspense>
  );
}

"use client";

import { useRef, useState } from "react";
import toast from "react-hot-toast";
import { useChatMessages } from "@/hooks/useProjectChat";
import { useProjectMembers } from "@/hooks/useProjectMembers";
import { cn, readAsDataURL } from "@/lib/utils";
import {
  ChevronDown,
  FileText,
  Flag,
  Loader2,
  MoreVertical,
  Paperclip,
  Send,
  X,
} from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuPortal,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

const FLAG_OPTIONS = [
  { value: "none", label: "No flag" },
  { value: "request", label: "Request" },
  { value: "task", label: "Task" },
  { value: "idea", label: "Idea" },
  { value: "problem", label: "Problem" },
  { value: "incident", label: "Incident" },
  { value: "decision", label: "Decision" },
];

const MAX_TEXTAREA_HEIGHT = 200;

/**
 * `flag`/`search` are passed through only so this component's own
 * useChatMessages(channelId, {flag, q}) call resolves to the SAME query key
 * MessageList is reading — React Query then shares one cache entry/poll
 * instead of this composer quietly running a second, differently-filtered
 * background query for mutations it doesn't otherwise need the data for.
 */
export function MessageComposer({
  channelId,
  projectId,
  flag,
  search,
  replyTo,
  onCancelReply,
}) {
  const { sendMessage, uploadAttachment } = useChatMessages(channelId, {
    flag,
    q: search,
  });
  const { members } = useProjectMembers(projectId);

  const [text, setText] = useState("");
  const [pending, setPending] = useState([]);
  const [uploading, setUploading] = useState(false);
  const [messageFlag, setMessageFlag] = useState("none");
  const [mentionQuery, setMentionQuery] = useState(null);
  const textareaRef = useRef(null);
  const fileRef = useRef(null);

  const autoGrow = (el) => {
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${Math.min(el.scrollHeight, MAX_TEXTAREA_HEIGHT)}px`;
  };

  const handleChange = (e) => {
    const value = e.target.value;
    setText(value);
    autoGrow(e.target);

    const cursor = e.target.selectionStart;
    const upToCursor = value.slice(0, cursor);
    const match = upToCursor.match(/@([^\s@]*)$/);
    setMentionQuery(match ? match[1] : null);
  };

  const insertMention = (name) => {
    const el = textareaRef.current;
    if (!el) return;
    const cursor = el.selectionStart;
    const upToCursor = text.slice(0, cursor);
    const replaced = upToCursor.replace(/@([^\s@]*)$/, `@${name} `);
    const next = replaced + text.slice(cursor);
    setText(next);
    setMentionQuery(null);
    requestAnimationFrame(() => el.focus());
  };

  const mentionCandidates =
    mentionQuery === null
      ? []
      : members
          .filter((m) =>
            m.name.toLowerCase().includes(mentionQuery.toLowerCase()),
          )
          .slice(0, 5);

  const handleFiles = async (e) => {
    const files = Array.from(e.target.files || []);
    if (files.length === 0) return;
    setUploading(true);
    try {
      for (const file of files) {
        const allowed =
          file.type.startsWith("image/") || file.type === "application/pdf";
        if (!allowed) {
          toast.error("Only images and PDF files are allowed");
          continue;
        }
        if (file.size > 10 * 1024 * 1024) {
          toast.error(`${file.name} is larger than 10MB`);
          continue;
        }
        const dataUri = await readAsDataURL(file);
        const result = await uploadAttachment.mutateAsync({
          file: dataUri,
          name: file.name,
          projectId,
        });
        setPending((prev) => [...prev, result]);
      }
    } catch (err) {
      toast.error(err.response?.data?.error || "Upload failed");
    } finally {
      setUploading(false);
      if (fileRef.current) fileRef.current.value = "";
    }
  };

  const handleSend = async () => {
    if (!text.trim() && pending.length === 0) return;
    try {
      await sendMessage.mutateAsync({
        body: text.trim(),
        attachments: pending,
        flag: messageFlag,
        replyToMessageId: replyTo?._id || undefined,
      });
      setText("");
      setPending([]);
      setMessageFlag("none");
      onCancelReply?.();
      if (textareaRef.current) textareaRef.current.style.height = "auto";
    } catch (err) {
      toast.error(err.response?.data?.error || "Failed to send");
    }
  };

  // Enter alone is left completely alone — the textarea's own default
  // behavior (a newline) is exactly what's wanted. Only Ctrl/Cmd+Enter sends.
  const handleKeyDown = (e) => {
    if (e.key === "Enter" && (e.ctrlKey || e.metaKey)) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="border-t border-white/10 shrink-0">
      {replyTo && (
        <div className="flex items-center justify-between gap-2 px-4 pt-2 text-xs text-gray-400">
          <span className="truncate">
            Replying to <strong className="text-gray-300">{replyTo.authorName}</strong>:{" "}
            {replyTo.body}
          </span>
          <button
            type="button"
            onClick={onCancelReply}
            className="text-gray-500 hover:text-white shrink-0"
          >
            <X className="w-3.5 h-3.5" />
          </button>
        </div>
      )}

      {pending.length > 0 && (
        <div className="px-4 pt-2 flex flex-wrap gap-2">
          {pending.map((a, idx) => (
            <span
              key={idx}
              className="flex items-center gap-1 text-xs bg-white/10 text-gray-200 rounded px-2 py-1"
            >
              {a.type === "pdf" ? (
                <FileText className="w-3 h-3" />
              ) : (
                <Paperclip className="w-3 h-3" />
              )}
              {a.name || a.type}
              <button
                type="button"

                type="button"
                onClick={() =>
                  setPending((prev) => prev.filter((_, i) => i !== idx))
                }
                className="hover:text-red-400"
              >
                <X className="w-3 h-3" />
              </button>
            </span>
          ))}
        </div>
      )}

      <div className="flex items-center gap-2 px-3 md:px-4 py-3">
        <input
          ref={fileRef}
          type="file"
          accept="image/*,application/pdf"
          multiple
          onChange={handleFiles}
          className="hidden"
        />

        {/* Mobile: one ⋮ button folding Attach and Flag away, so the text
            field gets the width instead of two controls that are used far
            less often than typing. Desktop keeps them as direct buttons. */}
        <DropdownMenu>
          <DropdownMenuTrigger
            className={cn(
              "md:hidden shrink-0 p-2 rounded-lg transition-colors",
              messageFlag !== "none"
                ? "text-[#FFB633]"
                : "text-gray-400 hover:text-white",
            )}
            title="Attach or flag"
          >
            {uploading ? (
              <Loader2 className="w-5 h-5 animate-spin" />
            ) : (
              <MoreVertical className="w-5 h-5" />
            )}
          </DropdownMenuTrigger>
          <DropdownMenuContent
            side="top"
            align="start"
            className="bg-[#1a1a1b] border-white/10 text-gray-200"
          >
            <DropdownMenuItem
              onClick={() => fileRef.current?.click()}
              disabled={uploading}
              className="gap-2 cursor-pointer"
            >
              <Paperclip className="w-3.5 h-3.5" /> Attach image or PDF
            </DropdownMenuItem>
            <DropdownMenuSub>
              <DropdownMenuSubTrigger className="gap-2 cursor-pointer">
                <Flag className="w-3.5 h-3.5" />
                Flag
                <span className="ml-auto pl-2 text-[10px] text-gray-500">
                  {FLAG_OPTIONS.find((o) => o.value === messageFlag)?.label}
                </span>
              </DropdownMenuSubTrigger>
              <DropdownMenuPortal>
                <DropdownMenuSubContent className="bg-[#1a1a1b] border-white/10 text-gray-200">
                  {FLAG_OPTIONS.map((opt) => (
                    <DropdownMenuItem
                      key={opt.value}
                      onClick={() => setMessageFlag(opt.value)}
                      className="cursor-pointer"
                    >
                      {opt.label}
                    </DropdownMenuItem>
                  ))}
                </DropdownMenuSubContent>
              </DropdownMenuPortal>
            </DropdownMenuSub>
          </DropdownMenuContent>
        </DropdownMenu>

        <button
          type="button"
          onClick={() => fileRef.current?.click()}
          disabled={uploading}
          className="hidden md:block p-2 text-gray-400 hover:text-[#FFB633] transition-colors shrink-0"
          title="Attach image or PDF"
        >
          {uploading ? (
            <Loader2 className="w-5 h-5 animate-spin" />
          ) : (
            <Paperclip className="w-5 h-5" />
          )}
        </button>

        <DropdownMenu>
          <DropdownMenuTrigger
            className={cn(
              "hidden md:flex shrink-0 items-center gap-1 px-2.5 py-2 text-xs rounded-lg border transition-colors",
              messageFlag !== "none"
                ? "border-[#FFB633] text-[#FFB633]"
                : "border-white/10 text-gray-400 hover:text-white",
            )}
          >
            {FLAG_OPTIONS.find((o) => o.value === messageFlag)?.label}
            <ChevronDown className="w-3 h-3" />
          </DropdownMenuTrigger>
          <DropdownMenuContent className="bg-[#1a1a1b] border-white/10 text-gray-200">
            {FLAG_OPTIONS.map((opt) => (
              <DropdownMenuItem
                key={opt.value}
                onClick={() => setMessageFlag(opt.value)}
                className="cursor-pointer"
              >
                {opt.label}
              </DropdownMenuItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>

        <div className="relative flex-1">
          <textarea
            ref={textareaRef}
            value={text}
            onChange={handleChange}
            onKeyDown={handleKeyDown}
            placeholder="Type a message… (Enter for new line, Ctrl+Enter to send)"
            rows={1}
            className="w-full bg-white/5 border border-white/10 text-white rounded-xl px-4 py-2 text-sm focus:outline-none focus:border-[#FFB633]/50 resize-none overflow-y-auto"
            style={{ maxHeight: MAX_TEXTAREA_HEIGHT }}
          />
          {mentionCandidates.length > 0 && (
            <div className="absolute bottom-full mb-1 left-0 w-56 bg-[#1a1a1b] border border-white/10 rounded-lg shadow-lg overflow-hidden z-10">
              {mentionCandidates.map((m) => (
                <button
                  key={m.userId}
                  type="button"
                  onClick={() => insertMention(m.name)}
                  className="w-full text-left px-3 py-2 text-sm text-gray-200 hover:bg-white/10"
                >
                  {m.name}
                </button>
              ))}
            </div>
          )}
        </div>

        <button
          type="button"
          onClick={handleSend}
          disabled={sendMessage.isPending || (!text.trim() && pending.length === 0)}
          className="p-2 bg-[#FFB633] text-black rounded-full hover:bg-[#e5a32e] disabled:opacity-50 transition-colors shrink-0"
        >
          <Send className="w-5 h-5" />
        </button>
      </div>
    </div>
  );
}

